import starter from './starter.json';

// The world layout is generated by tools/art/build.py (together with the baked
// ground image), so art and collision always match.

export enum Tile {
  Grass,
  Flowers,
  Path,
  Stone,
  Water,
  Bridge,
}

export interface Prop {
  kind: 'tree' | 'rock' | 'bush' | 'house' | 'post';
  x: number;
  y: number; // grid; houses occupy 2x2 starting here
  variant: number;
}

export interface NpcDef {
  id: string;
  name: string;
  texture: string;
  x: number;
  y: number;
}

export interface SpawnZone {
  monster: 'slime' | 'wolf';
  x0: number;
  y0: number;
  x1: number;
  y1: number;
  count: number;
}

export interface WorldData {
  size: number;
  tiles: Tile[][];
  blocked: number[][];
  props: Prop[];
  playerStart: { x: number; y: number };
  npcs: NpcDef[];
  spawns: SpawnZone[];
  /** Art-pixel position of grid (0,0) inside the ground image. */
  groundOrigin: { x: number; y: number };
}

export function buildWorld(): WorldData {
  return starter as WorldData;
}
